import { relative, resolve, sep } from 'node:path';
import type { GraphqlOperation, RestOperation } from '@softistx/limix/coverage';
import { CodegenError } from './errors';
import { compareRest, compareText, uniqueSorted } from './order';

/** What the generated file registers; a key is written only when its source was given. */
export interface ModuleInput {
	/** The names of the inputs, for the header, in the order given. */
	sources: readonly string[];
	rest?: readonly RestOperation[];
	graphql?: readonly GraphqlOperation[];
	/** The end of the header's second line; the CLI's by default. */
	regenerate?: string;
}

const REGENERATE = 'run `limix-codegen generate` again (`--check` in CI)';

/**
 * Input names for the header: relative to the working directory, with `/`
 * separators, sorted by code unit, each once. The same inputs give the same
 * header whatever the flag order or the machine's absolute paths.
 */
export function sourceNames(paths: readonly string[]): string[] {
	const names = paths.map((path) =>
		relative(process.cwd(), resolve(path)).split(sep).join('/'),
	);
	return uniqueSorted(names, compareText);
}

const LINE_WIDTH = 80;

/**
 * A single-quoted string literal. Backslashes, quotes, line breaks and lone
 * surrogates are escaped, so the text always reads back as `value`.
 */
export function quote(value: string): string {
	const body = JSON.stringify(value)
		.slice(1, -1)
		.replace(/\\(.)|'/gs, (match, escaped?: string) =>
			escaped === '"' ? '"' : match === "'" ? "\\'" : match,
		);
	return `'${body}'`;
}

/** One union, on one line when it fits in 80 columns, else one member per line. */
function union(name: string, members: readonly string[]): string {
	if (members.length === 0) return `export type ${name} = never;`;
	const literals = members.map(quote);
	const line = `export type ${name} = ${literals.join(' | ')};`;
	if (line.length <= LINE_WIDTH) return line;
	const body = literals.map((literal) => `\t| ${literal}`).join('\n');
	return `export type ${name} =\n${body};`;
}

/** The type-only import of core, one name per line past 80 columns, as Biome writes it. */
function importLine(names: readonly string[]): string {
	const line = `import type { ${names.join(', ')} } from '@softistx/limix';`;
	if (line.length <= LINE_WIDTH) return line;
	const body = names.map((name) => `\t${name},`).join('\n');
	return `import type {\n${body}\n} from '@softistx/limix';`;
}

/** `export type <alias>`, laid out the way Biome writes it: the type arguments wrap past 80 columns. */
function aliasLine(alias: string, input: string): string {
	const head = `export type ${alias}<W extends string = ConditionName> = ${input}<`;
	const line = `${head}Register, W>;`;
	if (line.length <= LINE_WIDTH) return line;
	return `${head}\n\tRegister,\n\tW\n>;`;
}

/**
 * The generated file: unions of the operation names, and the
 * `declare module '@softistx/limix'` block that registers them. The output is
 * sorted, LF, with a fixed two-line header, so the same inputs always give the
 * same bytes.
 */
export function generateModule(input: ModuleInput): string {
	const { rest, graphql } = input;
	if (!rest && !graphql) {
		throw new CodegenError('nothing to generate: no OpenAPI or GraphQL');
	}
	const blocks: string[] = [];
	const keys: string[] = [];
	const imports = ['ConditionName'];
	const add = (
		key: string,
		local: string,
		members: readonly string[],
		input: string,
		alias: string,
	) => {
		blocks.push(union(local, members));
		blocks.push(aliasLine(alias, input));
		imports.push(input);
		keys.push(`\t\t${key}: ${local};`);
	};
	if (rest) {
		const sorted = uniqueSorted(
			rest.map((o) => ({ method: o.method.toUpperCase(), path: o.path })),
			compareRest,
			(o) => `${o.method} ${o.path}`,
		);
		add(
			'rest',
			'LimixRest',
			sorted.map((o) => `${o.method} ${o.path}`),
			'RestRulesInput',
			'RestRules',
		);
	}
	if (graphql) {
		const labels = graphql.map((o) => `${o.type}.${o.field}`);
		add(
			'graphql',
			'LimixGraphql',
			uniqueSorted(labels, compareText),
			'GraphqlRulesInput',
			'GraphqlRules',
		);
	}
	return [
		`// Generated by @softistx/limix-codegen from ${input.sources.join(', ')}.`,
		`// Do not edit: ${input.regenerate ?? REGENERATE}.`,
		'',
		importLine([...imports, 'Register'].sort(compareText)),
		'',
		blocks.join('\n'),
		'',
		"declare module '@softistx/limix' {",
		'\tinterface Register {',
		...keys,
		'\t}',
		'}',
		'',
	].join('\n');
}
